// 3. กรองข้อมูล: ตรวจสอบวันหมดอายุ (Expiry_Date) ตามรอบ R1 / R2
const results = [];
const DAY_MS = 24 * 60 * 60 * 1000;
const { r1_days: R1_DAYS, r2_days: R2_DAYS } = $('Load Settings').first().json;

// วันนี้ตามเวลาไทย (ไม่ขึ้นกับ timezone ของเครื่องที่รัน n8n) เก็บเป็น UTC midnight เพื่อเทียบจำนวนวันตรงๆ
const [ty, tm, td] = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Bangkok' }).split('-').map(Number);
const todayMs = Date.UTC(ty, tm - 1, td);

// อ่านวันที่จากชีต: รองรับ yyyy-mm-dd และ dd/mm/yyyy (รูปแบบไทย) รวมปี พ.ศ.
// ถ้าเลขกลางเกิน 12 แต่เลขหน้าไม่เกิน 12 ถือว่าเป็น mm/dd/yyyy แล้วสลับให้ (ชีตตั้ง locale สหรัฐ)
function parseSheetDate(raw) {
  const s = String(raw).trim();
  let y, m, d;
  let hit = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (hit) { y = +hit[1]; m = +hit[2]; d = +hit[3]; }
  else if ((hit = s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})/))) {
    d = +hit[1]; m = +hit[2]; y = +hit[3];
    if (m > 12 && d <= 12) [d, m] = [m, d];
  } else return null;
  if (y > 2400) y -= 543;
  if (m < 1 || m > 12 || d < 1 || d > 31) return null;
  return Date.UTC(y, m - 1, d);
}

for (const item of $input.all()) {
  const row = item.json;

  const name = row['Customer_Name'] || row['Name'] || row['ชื่อ'] || row['name'] || '';
  const email = row['Email'] || row['email'] || row['อีเมล'] || '';
  const expiryDateRaw = row['Expiry_Date'] || row['due_date_to'] || row['dueDate'] || row['insurance_date_to'] || '';
  const policyNo = row['Policy_No'] || row['policy'] || '';
  const insuranceType = row['Insurance_Type'] || row['type'] || 'ประกันภัย';

  const r1Status = (row['Mail_R1_Status'] || '').trim();
  const r2Status = (row['Mail_R2_Status'] || '').trim();
  const done = s => ['Sent', 'สำเร็จ', 'Skipped'].includes(s); // Skipped = ตั้งใจไม่ส่งรอบนั้น
  const dataStatus = (row['Data_Status'] || 'Valid').trim();
  // สถานะลูกค้าหลังโทรติดตาม (ตั้งจากหน้าเว็บ) เช่น 'ยังไม่สนใจ', 'ไม่ติดต่อ / ปิดงาน'
  // 'ปิดงาน' หยุดทุกรอบ, 'ไม่สนใจ' หยุดเฉพาะรอบ 3 เดือน (R2)
  const customerStatus = String(row['Customer_Status'] || row['customerStatus'] || '').replace(/\s+/g, '');
  const closed = customerStatus.includes('ปิดงาน');
  const notInterested = customerStatus.includes('ไม่สนใจ');

  // ข้ามรายการที่ไม่มี email หรือถูกระบุว่า Invalid
  // ส่งเฉพาะข้อมูลที่ Valid (ว่าง = Valid) ข้าม Invalid / Needs Review และลูกค้าที่ปิดงานแล้ว
  if (!email || dataStatus !== 'Valid' || closed) {
    continue;
  }

  if (!expiryDateRaw) continue;
  const expiryMs = parseSheetDate(expiryDateRaw);
  if (expiryMs === null) continue;

  // คำนวณจำนวนวันก่อนหมดอายุ
  const diffDays = Math.round((expiryMs - todayMs) / DAY_MS);

  let targetRound = null;
  let roundLabel = '';
  let monthsAhead = 0;

  // R1: เหลือ (r2_days, r1_days] วัน / R2: เหลือ (0, r2_days] วัน (จำนวนวันจากชีต config)
  // ลูกค้าที่เข้ามาเมื่อเลยช่วง R1 แล้ว ได้แค่ R2 (ไม่ส่ง R1 ย้อนหลัง)
  if (diffDays > R2_DAYS && diffDays <= R1_DAYS) {
    if (!done(r1Status)) {
      targetRound = 'R1';
      monthsAhead = Math.round(R1_DAYS / 30);
      roundLabel = `ล่วงหน้า ${monthsAhead} เดือน`;
    }
  }
  else if (diffDays > 0 && diffDays <= R2_DAYS) {
    if (!done(r2Status) && !notInterested) {
      targetRound = 'R2';
      monthsAhead = Math.round(R2_DAYS / 30);
      roundLabel = `ล่วงหน้า ${monthsAhead} เดือน`;
    }
  }

  if (targetRound) {
    results.push({
      json: {
        ...row,
        resolved_name: name || 'คุณลูกค้า',
        resolved_email: email,
        resolved_due_date: expiryDateRaw,
        policy_no: policyNo,
        customer_id: row['ID'] || row['id'] || row['No'] || row['No.'] || '',
        insurance_type: insuranceType,
        mail_round: targetRound,
        round_label: roundLabel,
        months_ahead: monthsAhead,
        days_remaining: diffDays,
        row_number: row.row_number || item.pairedItem?.item || null
      }
    });
  }
}

return results;

// 4.1-4.2 เติมค่าลงใน Template ที่ดึงจากชีต Templates (ดู node "Pick Templates")
// ตัวแปรที่ใช้ใน template ได้: {{customerName}} {{policyNo}} {{bookingNo}} {{policyExpiry}} {{insuranceType}}
//                              {{roundLabel}} {{monthsAhead}} {{daysRemaining}} {{driveLinks}} {{referenceId}}
const record = $input.item.json;
// โหมดทดสอบ: ถ้า Global Config.test_recipient_email ไม่ว่าง จะส่งทุกฉบับไปที่อีเมลนั้นแทนอีเมลลูกค้า
const testTo = String($('Global Config').first().json.test_recipient_email || '').trim();
const tpl = $('Pick Templates').first().json[record.mail_round]; // R1 | R2

// สร้าง Message-ID เฉพาะสำหรับใช้อ้างอิง
const customMessageId = `<n8n-${Date.now()}-${Math.random().toString(36).substring(2, 9)}@automail.internal>`;

const att = $('Collect Attachments').first();

const policyNo = record.policy_no || 'POL-REF';
const vars = {
  customerName: record.resolved_name,
  policyNo,
  bookingNo: policyNo,
  policyExpiry: record.resolved_due_date,
  insuranceType: record.insurance_type || 'ประกันภัย',
  roundLabel: record.round_label,
  monthsAhead: record.months_ahead,
  daysRemaining: record.days_remaining,
  driveLinks: att.json.attachment_names,
  referenceId: customMessageId
};

const esc = s => s.replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const fill = (text, escape) => text.replace(/\{\{\s*(\w+)\s*\}\}/g, (_, k) => {
  const v = String(vars[k] ?? '');
  return escape ? esc(v) : v;
});

return {
  json: {
    ...record,
    mail_subject: (testTo ? '[TEST] ' : '') + fill(tpl.subject, false),
    send_to: testTo || record.resolved_email,
    mail_html: fill(tpl.html, true),
    generated_message_id: customMessageId,
    sent_date: new Date().toISOString().split('T')[0]
  },
  binary: att.binary || {}
};

// บันทึก log สถานะสำเร็จเพื่อนำไปรวมส่งรายงานสรุป
const template = $('4.1-4.2 Build Mail Template').item.json;
return {
  json: {
    is_success: true,
    name: template.resolved_name,
    email: template.resolved_email,
    message_id: template.generated_message_id,
    mail_round: template.mail_round,
    round_label: template.round_label,
    reason: 'Success'
  }
};

// บันทึก log สถานะไม่สำเร็จเพื่อนำไปรวมส่งรายงานสรุป
const template = $('4.1-4.2 Build Mail Template').item.json;
const err = $('4.2 Send Email (SMTP)').item.json.error;
const errMsg = (typeof err === 'string' ? err : err?.message) || 'SMTP Error';
return {
  json: {
    is_success: false,
    name: template.resolved_name,
    email: template.resolved_email,
    message_id: template.generated_message_id,
    mail_round: template.mail_round,
    round_label: template.round_label,
    reason: errMsg
  }
};

// 5. สรุปผลการส่ง Auto Email ทั้งหมดในรอบนี้ แยกตาม R1 / R2
// ผู้รับจาก config: admin_report_email (คั่นด้วย , ได้) ว่าง = ไม่ส่งรายงาน
const S = $('Load Settings').first().json;
if (!S.report_to) return [];
let successLogs = [];
let failLogs = [];

try {
  successLogs = $('Log Success Result').all().map(i => i.json);
} catch (e) {}

try {
  failLogs = $('Log Failure Result').all().map(i => i.json);
} catch (e) {}

const totalSuccess = successLogs.length;
const totalFailed = failLogs.length;
const totalProcessed = totalSuccess + totalFailed;

const r1Count = successLogs.filter(l => l.mail_round === 'R1').length;
const r2Count = successLogs.filter(l => l.mail_round === 'R2').length;

const nowStr = new Date().toLocaleString('th-TH', { timeZone: 'Asia/Bangkok' });

let htmlReport = `
<div style="font-family: Arial, sans-serif; line-height: 1.5; color: #222;">
  <h2>📊 รายงานผลการส่ง Auto Email ประจำรอบ (R1 & R2)</h2>
  <p><strong>เวลาประมวลผล:</strong> ${nowStr}</p>
  <table border="1" cellpadding="8" cellspacing="0" style="border-collapse: collapse; width: 100%; max-width: 600px;">
    <tr style="background-color: #f2f2f2;"><th>รายการ</th><th>จำนวน</th></tr>
    <tr><td>ทั้งหมดที่เข้าเงื่อนไข</td><td><strong>${totalProcessed}</strong></td></tr>
    <tr style="color: #1a73e8;"><td>R1 (${S.r1_days} วันก่อนหมดอายุ) ส่งสำเร็จ</td><td><strong>${r1Count}</strong></td></tr>
    <tr style="color: #d93025;"><td>R2 (${S.r2_days} วันก่อนหมดอายุ) ส่งสำเร็จ</td><td><strong>${r2Count}</strong></td></tr>
    <tr style="color: green;"><td>ส่งสำเร็จรวม</td><td><strong>${totalSuccess}</strong></td></tr>
    <tr style="color: red;"><td>ไม่สำเร็จ</td><td><strong>${totalFailed}</strong></td></tr>
  </table>
`;

if (totalFailed > 0) {
  htmlReport += `
  <h3 style="color: red; margin-top: 20px;">⚠️ รายการที่ไม่สำเร็จ:</h3>
  <ul>
    ${failLogs.map(f => `<li><strong>${f.name}</strong> (${f.email}) [${f.round_label || ''}] - เหตุผล: ${f.reason}</li>`).join('')}
  </ul>
  `;
}

htmlReport += `
  <hr style="margin-top: 30px; border: none; border-top: 1px solid #ccc;" />
  <p style="font-size: 12px; color: #666;">รายงานนี้สร้างขึ้นโดยระบบอัตโนมัติ n8n AutoMail</p>
</div>
`;

return {
  json: {
    total_processed: totalProcessed,
    total_success: totalSuccess,
    total_failed: totalFailed,
    r1_success: r1Count,
    r2_success: r2Count,
    report_to: S.report_to,
    report_html: htmlReport,
    report_subject: `[Auto Mail Report] สรุปผลส่งอีเมล R1 & R2 (สำเร็จ: ${totalSuccess}, ล้มเหลว: ${totalFailed})`
  }
};

// เลือก Template ของรอบ R1/R2 จากชีต Templates (ค้นด้วยคอลัมน์ Template_Name; ชื่อกำหนดใน Global Config)
// หัวคอลัมน์แถวที่ 1 ของชีต: Template_ID, Template_Name, Subject, Recipient_Type, Status, Description, HTML_Content
const cfg = $('Global Config').first().json;
const rows = $input.all().map(i => i.json);

const need = ['Template_Name', 'Subject', 'Status', 'HTML_Content'];
const have = Object.keys(rows[0] || {});
const missing = need.filter(k => !have.includes(k));
if (missing.length) {
  throw new Error(`ชีต Templates: ไม่พบหัวคอลัมน์ [${missing.join(', ')}] (หัวที่พบ: ${have.join(', ') || 'ไม่มีข้อมูล'})`);
}

const pick = round => {
  const name = cfg[`template_name_${round.toLowerCase()}`];
  const row = rows.find(r => String(r.Template_Name || '').trim() === name);
  if (!row) throw new Error(`ชีต Templates: ไม่พบ template ชื่อ "${name}" (รอบ ${round})`);
  if ((row.Status || 'Active').trim() !== 'Active') throw new Error(`ชีต Templates: template "${name}" ไม่ได้เป็น Active`);
  if (!row.Subject || !row.HTML_Content) throw new Error(`ชีต Templates: template "${name}" ไม่มี Subject หรือ HTML_Content`);
  return { subject: row.Subject, html: row.HTML_Content };
};

return [{ json: { R1: pick('R1'), R2: pick('R2') } }];

// อ่านชีต config: SYSTEM (เกณฑ์รอบ R1/R2, ผู้รับรายงาน) และ DRIVE_LINK (Reminder Attachment)
// ค่าเกณฑ์รอบผิด/ว่าง = หยุดทั้งรอบ ไม่เดาค่า default เพราะเป็นการส่งเมลถึงลูกค้า
const sys = {};
const driveFiles = [];
for (const i of $input.all()) {
  const r = i.json;
  const cat = String(r.Category || '').trim().toUpperCase();
  const key = String(r.Key || '').trim();
  const value = String(r.Value || '').trim();
  if (cat === 'SYSTEM') sys[key] = value;
  if (cat === 'DRIVE_LINK' && value) {
    const m = value.match(/\/d\/([\w-]{10,})/) || value.match(/[?&]id=([\w-]{10,})/) || value.match(/^([\w-]{20,})$/);
    if (!m) throw new Error(`config DRIVE_LINK "${key}": อ่าน file ID จากลิงก์ไม่ได้ (${value})`);
    driveFiles.push({ name: key, fileId: m[1] });
  }
}

const days = k => {
  const v = sys[k];
  if (!/^\d+$/.test(v || '') || +v < 1) throw new Error(`config SYSTEM ${k} ต้องเป็นจำนวนวันเต็มบวก (ค่าปัจจุบัน: "${v ?? ''}")`);
  return +v;
};
const r1 = days('r1_days_before');
const r2 = days('r2_days_before');
if (r2 >= r1) throw new Error(`config: r2_days_before (${r2}) ต้องน้อยกว่า r1_days_before (${r1})`);

const reportTo = String(sys.admin_report_email || '').split(',').map(s => s.trim()).filter(Boolean);

return [{ json: { r1_days: r1, r2_days: r2, report_to: reportTo.join(', '), drive_files: driveFiles } }];

// 1 item ต่อ 1 Reminder Attachment; ไม่มีเลย = 1 item ว่าง (ผ่าน IF ไปขั้นถัดไปโดยไม่ดาวน์โหลด)
const files = $('Load Settings').first().json.drive_files;
return files.length ? files.map(f => ({ json: f })) : [{ json: { fileId: '' } }];

// รวมไฟล์ที่ดาวน์โหลดได้เป็น item เดียว (att0, att1, ...) ให้ทุกเมลแนบชุดเดียวกัน
const binary = {};
const names = [];
$input.all().forEach(i => {
  const b = i.binary?.data;
  if (!b) return;
  binary['att' + names.length] = b;
  names.push(b.fileName || i.json.name || `file${names.length + 1}`);
});
return [{ json: { attachment_keys: Object.keys(binary).join(','), attachment_names: names.join(', ') }, binary }];
